mapper.select:
SELECT d.id AS deptId, COALESCE(d.dept_name, '未分配部门') AS deptName, COUNT(DISTINCT s.employee_id) AS employeeCount, COALESCE(SUM(s.checkin_count), 0) AS checkinCount, SUM(CASE WHEN s.status = 'NORMAL' THEN 1 ELSE 0 END) AS normalDays, SUM(CASE WHEN s.status = 'LATE' THEN 1 ELSE 0 END) AS lateDays, SUM(CASE WHEN s.status = 'EARLY' THEN 1 ELSE 0 END) AS earlyDays, SUM(CASE WHEN s.status = 'ABSENT' THEN 1 ELSE 0 END) AS absentDays, SUM(CASE WHEN s.status = 'LEAVE' THEN 1 ELSE 0 END) AS leaveDays, COALESCE(ROUND(AVG(CASE WHEN s.work_minutes > 0 THEN s.work_minutes END)), 0) AS avgWorkMinutes, COALESCE(ROUND(SUM(CASE WHEN s.status IN ('NORMAL', 'LATE', 'EARLY') THEN 1 ELSE 0 END) * 100.0 / NULLIF(SUM(CASE WHEN s.status NOT IN ('REST', 'LEAVE') THEN 1 ELSE 0 END), 0), 1), 0) AS attendanceRate FROM att_daily_stat s JOIN hr_employee e ON e.id = s.employee_id LEFT JOIN org_department d ON d.id = e.dept_id
s.stat_date BETWEEN CAST(#{dateFrom} AS date) AND CAST(#{dateTo} AS date) AND e.dept_id = #{deptId} AND s.employee_id = #{employeeId}
GROUP BY d.id, d.dept_name ORDER BY checkinCount DESC

SELECT p.id AS placeId, p.place_name AS placeName, EXTRACT(HOUR FROM r.checkin_time) AS hour, COUNT(*) AS count FROM att_record r JOIN biz_place p ON p.id = r.place_id JOIN hr_employee e ON e.id = r.employee_id
r.checkin_time >= CAST(#{dateFrom} AS timestamp) AND r.checkin_time < CAST(#{dateTo} AS date) + INTERVAL '1 day' AND r.place_id = #{placeId} AND e.dept_id = #{deptId} AND r.employee_id = #{employeeId}
GROUP BY p.id, p.place_name, EXTRACT(HOUR FROM r.checkin_time) ORDER BY p.id, hour

SELECT p.id AS placeId, p.place_name AS placeName, -1 AS hour, COUNT(*) AS count FROM att_record r JOIN biz_place p ON p.id = r.place_id JOIN hr_employee e ON e.id = r.employee_id
r.checkin_time >= CAST(#{dateFrom} AS timestamp) AND r.checkin_time < CAST(#{dateTo} AS date) + INTERVAL '1 day' AND e.dept_id = #{deptId} AND r.employee_id = #{employeeId}
GROUP BY p.id, p.place_name ORDER BY count DESC

SELECT e.id AS employeeId, e.name AS employeeName, COALESCE(d.dept_name, '未分配部门') AS deptName, CASE WHEN EXISTS (SELECT 1 FROM att_record r WHERE r.employee_id = e.id AND r.checkin_time >= #{dayStart} AND r.checkin_time < #{dayEnd}) THEN 'CHECKED' WHEN EXISTS (SELECT 1 FROM biz_application a WHERE a.employee_id = e.id AND a.type = 'LEAVE' AND a.status = 'APPROVED' AND a.start_time <= #{dayEnd} AND a.end_time >= #{dayStart}) THEN 'LEAVE' ELSE 'ABSENT' END AS status FROM hr_employee e LEFT JOIN org_department d ON d.id = e.dept_id
e.status = 1 AND e.dept_id = #{deptId} AND e.id = #{employeeId}
ORDER BY e.id

SELECT s.stat_date AS date, COALESCE(ROUND(AVG(CASE WHEN s.work_minutes > 0 THEN s.work_minutes END) / 60.0, 1), 0) AS avgHours, COUNT(CASE WHEN s.work_minutes > 0 THEN 1 END) AS coveredEmployees FROM att_daily_stat s JOIN hr_employee e ON e.id = s.employee_id
s.stat_date BETWEEN CAST(#{dateFrom} AS date) AND CAST(#{dateTo} AS date) AND e.dept_id = #{deptId} AND s.employee_id = #{employeeId}
GROUP BY s.stat_date ORDER BY s.stat_date
